j = _item["json"]

# Extract text from Claude's response
text = ""
content = j.get("content", [])
if isinstance(content, list) and len(content) > 0:
    text = content[0].get("text", "")

clean = text.strip()
if clean.startswith("```"):
    lines = clean.split("\n")
    lines = lines[1:-1]
    clean = "\n".join(lines)

def extract_value(text, key):
    search = '"' + key + '":'
    idx = text.find(search)
    if idx == -1:
        return None
    start = idx + len(search)
    rest = text[start:].strip()
    if rest.startswith('"'):
        end = rest.find('"', 1)
        return rest[1:end]
    elif rest.startswith('['):
        end = rest.find(']')
        arr_str = rest[1:end]
        items_list = [x.strip().strip('"') for x in arr_str.split(',') if x.strip()]
        return ", ".join(items_list)
    elif rest.startswith('true'):
        return True
    elif rest.startswith('false'):
        return False
    else:
        end = 0
        while end < len(rest) and rest[end] not in [',', '}', '\n']:
            end += 1
        val = rest[:end].strip()
        try:
            return int(val)
        except:
            return val

return {"json": {
    "linkedin_id":          extract_value(clean, "linkedin_id"),
    "score":                extract_value(clean, "score"),
    "reason":               extract_value(clean, "reason"),
    "matched_skills":       extract_value(clean, "matched_skills"),
    "missing_skills":       extract_value(clean, "missing_skills"),
    "experience_required":  extract_value(clean, "experience_required"),
    "german_required":      extract_value(clean, "german_required"),
    "job_type_flag":        extract_value(clean, "job_type_flag"),
    "apply_recommendation": extract_value(clean, "apply_recommendation"),
}}
